def completar_usuario_nombre(apps, schema_editor):
    """Copia el username en los registros existentes (para búsquedas y filtros)."""
    Auditoria = apps.get_model('auditoria', 'Auditoria')
    for registro in Auditoria.objects.filter(usuario__isnull=False).select_related('usuario').iterator():
        registro.usuario_nombre = registro.usuario.username
        registro.save(update_fields=['usuario_nombre'])


